    private ApiDefinitions() {}

    private static void add(ApiDefinition definition) {
        ALL.add(definition);
        BY_API_NAME.put(definition.getApiName(), definition);
        BY_METHOD_NAME.put(definition.getMethodName(), definition);
    }

    public static List<ApiDefinition> all() { return Collections.unmodifiableList(ALL); }

    public static ApiDefinition get(String apiName) {
        ApiDefinition definition = BY_API_NAME.get(apiName);
        return definition != null ? definition : BY_METHOD_NAME.get(apiName);
    }
